import unittest

from files import UnsafePath, resolve_download


class FileServiceTests(unittest.TestCase):
    def test_normal_name_stays_under_root(self):
        self.assertEqual(resolve_download("/srv/downloads", "report.csv").name, "report.csv")

    def test_traversal_is_rejected(self):
        with self.assertRaises(UnsafePath):
            resolve_download("/srv/downloads", "../../etc/passwd")
